        try c.transfer(from, caddress, _tos, v) returns (bool ok) {
            reverted = false;
            // also record returned value via ok to include in the final assertion
            if (!ok) {
                // nothing special; ok will be used in assertion below via ret encoding
            }
        } catch (bytes memory reason) {
            reverted = true;
            ret = reason;
        }

        // General rule: Given the function's implementation, for any valid inputs (non-empty _tos with matching v),
        // C.transfer must not revert and must return true. We assert that it did not revert.
        assert(reverted == false);
    }

    receive() external payable {}
